#include "doctor/ProjectDoctor.h"
#include <fstream>
namespace forge::doctor {std::vector<Issue> ProjectDoctor::scan(const std::filesystem::path&p)const{std::vector<Issue>r;if(!std::filesystem::exists(p/"ForgeProject.json"))r.push_back({Severity::Error,"PROJ001","Missing ForgeProject.json",p.string()});if(!std::filesystem::exists(p/"Scenes/Main.forgeScene"))r.push_back({Severity::Error,"SCN001","Default scene is missing","Scenes/Main.forgeScene"});if(!std::filesystem::exists(p/"Assets"))r.push_back({Severity::Warning,"AST001","Assets directory is missing","Assets"});for(auto&it:std::filesystem::recursive_directory_iterator(p)){if(it.path().extension()==".forgeScene"&&it.is_regular_file()){std::ifstream f(it.path());std::string s((std::istreambuf_iterator<char>(f)),{});if(s.find("entities")!=std::string::npos&&s.find("\"id\"")==std::string::npos)r.push_back({Severity::Warning,"SCN002","Scene has no entities",""});}}if(r.empty())r.push_back({Severity::Info,"OK","No structural project issues detected",p.string()});return r;}}
